mapper.select:
SELECT 
FROM agent_approval
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{limit}

mapper.update:
UPDATE agent_approval
SET execution_token_status = 'consumed',
    execution_token_consumed_at = #{consumedAt}
WHERE approval_id = #{approvalId}
  AND execution_token = #{token}
  AND execution_token_status = 'issued'

UPDATE agent_approval
SET status = #{status}
WHERE id = #{id}
  AND status = 'approved'
